import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {expect} from '@playwright/test';
import type {AuthoringArchive} from '../../packages/compatibility/src/authoring-archive';
/** Generated by the codec integration test; historical external file never overwritten. */
export async function registeredWorkbookCopy(path:string,directory='docs/architecture/evidence/full-current-2026-10-14/registered-copies'){
 const name=path.split('/').at(-1)!;
 const record=JSON.parse(readFileSync(`${directory}/${name}.json`,'utf8')) as {source:string;sourceSha256:string;original:Extract<AuthoringArchive,{format:'knolstory'}>;archive:Extract<AuthoringArchive,{format:'knolstory'}>};
 expect(record.source).toBe(path);expect(createHash('sha256').update(readFileSync(path)).digest('hex')).toBe(record.sourceSha256);
 return {...record,buffer:readFileSync(`${directory}/${name}`)};
}
